/**
 * naci.session/1 — the integration boundary between NeuroAssist (parent A) and the
 * NeuroAssist x CI collective (child). Python mirror: naci/contract.py. Any change here is a
 * new schema version; both sides reject unknown versions.
 */
export const SESSION_SCHEMA = 'naci.session/1' as const;

/** REAL: captured by a NeuroAssist camera session. PRERECORDED: an exported file of unverified
 *  origin. SYNTHETIC: generated by NeuroAssist's simulator for demonstration or benchmarking. */
export type DataLabel = 'REAL' | 'PRERECORDED' | 'SYNTHETIC';

export interface SessionRecord {
  schema: typeof SESSION_SCHEMA;
  session_id: string;
  /** Pseudonymous subject id. Never a name or email. */
  subject_id: string;
  recorded_at: string; // ISO 8601
  protocol: 'FIXATION';
  provenance: {
    label: DataLabel;
    source: string; // e.g. "neuroassist-simulator", "neuroassist-live", "export:unverified"
    engine: string; // NeuroAssist ENGINE_VERSION that produced the measurement
    generator?: Record<string, unknown>; // synthetic only: the generator parameters, for audit
  };
  measurement: {
    status: 'MEASURED' | 'ABSTAINED';
    metric: 'SLOW_PHASE_VELOCITY';
    unit: 'deg/s';
    value: number | null;
    ci_low: number | null;
    ci_high: number | null;
    windows: number;
  };
  quality: {
    valid_frac: number;
    fps: number;
    noise_deg: number | null;
    residual_ratio: number | null;
    checks: { id: string; label: string; show: string; rule: string; ok: boolean }[];
    abstain_reasons: string[];
  };
  /** Gaze (deg) and head-rotation magnitude (deg) per frame. null = lost frame. Optional for
   *  history records; required for the session under analysis. */
  trace?: { t: number[]; x: (number | null)[]; head?: (number | null)[] };
}
